    /// </summary>
    public V1VideosResource Videos { get; }
}

/// <summary>
/// FinSocial. The groups on this object are the /api operations, charged in credits per call; the /v1 operations, included in paid plans, are under V1.
/// </summary>
public sealed class FinSocialResource
{
    internal FinSocialResource(FinHttpTransport http)
    {
        Markets = new MarketsResource(http);
        Social = new SocialResource(http);
        Videos = new VideosResource(http);
        V1 = new FinSocialV1Resource(http);
    }

    /// <summary>
    /// Markets.
    /// </summary>
